-- Tower scene receipts share the existing manager_jobs cost account.
CREATE TABLE tower_scenes(
 id TEXT PRIMARY KEY,scene_key TEXT NOT NULL,period_key TEXT UNIQUE,batch_id TEXT,
 baseline_sha TEXT NOT NULL CHECK(baseline_sha='6f68c848ff2883ef903521f709edc3f4c78356652cbfbd8975b4c285b76f5d96'),bible_version TEXT NOT NULL CHECK(bible_version='tower-v1'),
 state TEXT NOT NULL CHECK(state IN('pending','running','reviewed','published','blocked','unknown','invalid')),
 lifetime_budget INTEGER NOT NULL CHECK(lifetime_budget>0 AND lifetime_budget<=1000000000),daily_budget INTEGER NOT NULL CHECK(daily_budget>0 AND daily_budget<=1000000000),monthly_budget INTEGER NOT NULL CHECK(monthly_budget>0 AND monthly_budget<=1000000000),
 plan_json TEXT,review_json TEXT,object_key TEXT UNIQUE,sha256 TEXT,byte_length INTEGER,width INTEGER,height INTEGER,
 error_code TEXT,lease_until TEXT,created_at TEXT NOT NULL,published_at TEXT,
 CHECK((batch_id IS NOT NULL AND period_key IS NULL) OR (batch_id IS NULL AND period_key IS NOT NULL)),
 CHECK(state NOT IN('reviewed','published') OR (object_key IS NOT NULL AND sha256 IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL AND width>=1200 AND height>=750 AND width<=8192 AND height<=8192 AND width*height<=16000000 AND width*1.0/height>=1.4 AND width*1.0/height<=1.8 AND json_extract(review_json,'$.pass')=1))
);
CREATE UNIQUE INDEX tower_scene_seed_angle ON tower_scenes(scene_key) WHERE batch_id IS NOT NULL;
CREATE TABLE tower_scene_calls(scene_id TEXT NOT NULL REFERENCES tower_scenes(id),purpose TEXT NOT NULL CHECK(purpose IN('plan','image','review')),job_id TEXT NOT NULL UNIQUE REFERENCES manager_jobs(id),model TEXT NOT NULL,request_sha TEXT NOT NULL,created_at TEXT NOT NULL,owner_lease TEXT NOT NULL,PRIMARY KEY(scene_id,purpose));
CREATE TABLE tower_scene_periods(period_key TEXT PRIMARY KEY,scene_id TEXT NOT NULL REFERENCES tower_scenes(id),created_at TEXT NOT NULL);
CREATE TRIGGER tower_scene_seed_batch BEFORE INSERT ON tower_scenes WHEN NEW.batch_id IS NOT NULL AND ((SELECT count(*) FROM tower_scenes WHERE batch_id=NEW.batch_id)>=6 OR (SELECT count(*) FROM tower_scenes WHERE batch_id IS NOT NULL)>=10) BEGIN SELECT RAISE(ABORT,'scene_seed_batch_limit'); END;
CREATE TRIGGER tower_scene_binding BEFORE UPDATE ON tower_scenes WHEN NEW.id!=OLD.id OR NEW.scene_key!=OLD.scene_key OR NEW.period_key IS NOT OLD.period_key OR NEW.batch_id IS NOT OLD.batch_id OR NEW.baseline_sha!=OLD.baseline_sha OR NEW.bible_version!=OLD.bible_version OR NEW.created_at!=OLD.created_at OR NEW.lifetime_budget!=OLD.lifetime_budget OR NEW.daily_budget!=OLD.daily_budget OR NEW.monthly_budget!=OLD.monthly_budget OR OLD.state IN('published','blocked','invalid') OR (OLD.plan_json IS NOT NULL AND NEW.plan_json IS NOT OLD.plan_json) OR (OLD.object_key IS NOT NULL AND (NEW.object_key IS NOT OLD.object_key OR NEW.sha256 IS NOT OLD.sha256 OR NEW.byte_length IS NOT OLD.byte_length OR NEW.width IS NOT OLD.width OR NEW.height IS NOT OLD.height)) BEGIN SELECT RAISE(ABORT,'scene_immutable'); END;
CREATE TRIGGER tower_scene_call_scope BEFORE INSERT ON tower_scene_calls WHEN NOT EXISTS(SELECT 1 FROM tower_scenes s JOIN manager_jobs j ON j.id=NEW.job_id WHERE s.id=NEW.scene_id AND s.state='running' AND s.lease_until=NEW.owner_lease AND s.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND j.state='running' AND j.started_at=j.created_at AND NEW.created_at=j.started_at AND abs(julianday(j.started_at)-julianday('now'))<1.0/1440 AND substr(j.started_at,1,10)=date('now') AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_jobs)<=s.lifetime_budget AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_jobs WHERE substr(started_at,1,10)=date('now'))<=s.daily_budget AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_jobs WHERE substr(started_at,1,7)=strftime('%Y-%m','now'))<=s.monthly_budget AND j.source_digest='scene:'||s.id||':'||NEW.purpose AND ((NEW.purpose='image' AND NEW.model='muse-image-1.0' AND j.reserved_micro=10000) OR (NEW.purpose IN('plan','review') AND NEW.model='muse-spark-1.3' AND j.reserved_micro>0))) BEGIN SELECT RAISE(ABORT,'scene_call_scope'); END;
CREATE TRIGGER tower_scene_call_no_update BEFORE UPDATE ON tower_scene_calls BEGIN SELECT RAISE(ABORT,'scene_call_immutable'); END;
CREATE TRIGGER tower_scene_call_no_delete BEFORE DELETE ON tower_scene_calls BEGIN SELECT RAISE(ABORT,'scene_call_permanent'); END;
CREATE TRIGGER tower_scene_receipt_binding BEFORE UPDATE ON manager_jobs WHEN EXISTS(SELECT 1 FROM tower_scene_calls WHERE job_id=OLD.id) AND (NEW.id!=OLD.id OR NEW.source_digest!=OLD.source_digest OR NEW.reserved_micro!=OLD.reserved_micro OR NEW.started_at IS NOT OLD.started_at OR NEW.created_at!=OLD.created_at OR OLD.state!='running' OR (OLD.actual_micro IS NOT NULL AND (NEW.actual_micro IS NOT OLD.actual_micro OR NEW.input_tokens IS NOT OLD.input_tokens OR NEW.output_tokens IS NOT OLD.output_tokens OR NEW.provider_id IS NOT OLD.provider_id))) BEGIN SELECT RAISE(ABORT,'scene_receipt_immutable'); END;
CREATE TRIGGER tower_scene_receipt_no_delete BEFORE DELETE ON manager_jobs WHEN EXISTS(SELECT 1 FROM tower_scene_calls WHERE job_id=OLD.id) BEGIN SELECT RAISE(ABORT,'scene_receipt_permanent'); END;
CREATE TRIGGER tower_scene_receipt_no_replace BEFORE INSERT ON manager_jobs WHEN EXISTS(SELECT 1 FROM tower_scene_calls WHERE job_id=NEW.id) BEGIN SELECT RAISE(ABORT,'scene_receipt_permanent'); END;
CREATE TRIGGER tower_scene_publish BEFORE UPDATE OF state ON tower_scenes WHEN NEW.state IN('reviewed','published') AND NOT EXISTS(SELECT 1 FROM tower_scene_calls c JOIN manager_jobs j ON j.id=c.job_id WHERE c.scene_id=NEW.id AND c.purpose='review' AND j.state='complete' AND j.actual_micro IS NOT NULL AND j.actual_micro<=j.reserved_micro) BEGIN SELECT RAISE(ABORT,'scene_review_required'); END;
CREATE TRIGGER tower_scene_period_scope BEFORE INSERT ON tower_scene_periods WHEN NOT EXISTS(SELECT 1 FROM tower_scenes WHERE id=NEW.scene_id AND state='published' AND (period_key=NEW.period_key OR batch_id IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'scene_period_scope'); END;

CREATE TABLE tower_scene_results(job_id TEXT PRIMARY KEY REFERENCES manager_jobs(id),result_json TEXT NOT NULL CHECK(json_valid(result_json)));
CREATE TRIGGER tower_scene_result_scope BEFORE INSERT ON tower_scene_results WHEN NOT EXISTS(SELECT 1 FROM tower_scene_calls c JOIN manager_jobs j ON j.id=c.job_id WHERE c.job_id=NEW.job_id AND c.purpose IN('plan','review') AND j.state='running' AND j.actual_micro IS NOT NULL) BEGIN SELECT RAISE(ABORT,'scene_result_scope'); END;
CREATE TRIGGER tower_scene_result_update BEFORE UPDATE ON tower_scene_results BEGIN SELECT RAISE(ABORT,'scene_result_immutable'); END;
CREATE TRIGGER tower_scene_result_delete BEFORE DELETE ON tower_scene_results BEGIN SELECT RAISE(ABORT,'scene_result_permanent'); END;

CREATE TRIGGER tower_scene_initial BEFORE INSERT ON tower_scenes WHEN NEW.state!='pending' OR NEW.plan_json IS NOT NULL OR NEW.review_json IS NOT NULL OR NEW.object_key IS NOT NULL OR NEW.published_at IS NOT NULL OR EXISTS(SELECT 1 FROM tower_scenes WHERE id=NEW.id) OR NEW.scene_key NOT IN('arrival-court','atrium-lobby','reading-lounge','skybridge-garden','rooftop-greenhouse','rooftop-telescope','window-reading-nook','terrace-garden','shared-dining-terrace','elevated-arcade') BEGIN SELECT RAISE(ABORT,'scene_initial'); END;
CREATE TRIGGER tower_scene_batch_sequence BEFORE INSERT ON tower_scenes WHEN NEW.batch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tower_scenes WHERE batch_id=NEW.batch_id) AND EXISTS(SELECT 1 FROM tower_scenes WHERE batch_id IS NOT NULL AND state!='published') BEGIN SELECT RAISE(ABORT,'scene_seed_batch_pending'); END;
CREATE TRIGGER tower_scene_delete BEFORE DELETE ON tower_scenes BEGIN SELECT RAISE(ABORT,'scene_permanent'); END;
CREATE TRIGGER tower_scene_period_update BEFORE UPDATE ON tower_scene_periods BEGIN SELECT RAISE(ABORT,'scene_period_permanent'); END;
CREATE TRIGGER tower_scene_period_delete BEFORE DELETE ON tower_scene_periods BEGIN SELECT RAISE(ABORT,'scene_period_permanent'); END;
CREATE TRIGGER tower_scene_period_replace BEFORE INSERT ON tower_scene_periods WHEN EXISTS(SELECT 1 FROM tower_scene_periods WHERE period_key=NEW.period_key) BEGIN SELECT RAISE(ABORT,'scene_period_permanent'); END;
CREATE TRIGGER tower_scene_all_receipts BEFORE UPDATE OF state ON tower_scenes WHEN NEW.state IN('reviewed','published') AND (SELECT count(*) FROM tower_scene_calls c JOIN manager_jobs j ON j.id=c.job_id WHERE c.scene_id=NEW.id AND j.state='complete' AND j.actual_micro IS NOT NULL AND j.actual_micro<=j.reserved_micro)!=3 BEGIN SELECT RAISE(ABORT,'scene_receipts_incomplete'); END;
CREATE TRIGGER tower_scene_call_replace BEFORE INSERT ON tower_scene_calls WHEN EXISTS(SELECT 1 FROM tower_scene_calls WHERE (scene_id=NEW.scene_id AND purpose=NEW.purpose) OR job_id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'scene_call_permanent'); END;
CREATE TRIGGER tower_scene_result_replace BEFORE INSERT ON tower_scene_results WHEN EXISTS(SELECT 1 FROM tower_scene_results WHERE job_id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'scene_result_permanent'); END;
-- The maintainer requested three private previews before continuing the initial ten.
CREATE TABLE tower_scene_style_approval(id INTEGER PRIMARY KEY CHECK(id=1),baseline_sha TEXT NOT NULL CHECK(baseline_sha='6f68c848ff2883ef903521f709edc3f4c78356652cbfbd8975b4c285b76f5d96'),bible_version TEXT NOT NULL CHECK(bible_version='tower-v1'),approved_at TEXT NOT NULL,detail_json TEXT NOT NULL CHECK(json_valid(detail_json)));
CREATE TRIGGER tower_scene_style_scope BEFORE INSERT ON tower_scene_style_approval WHEN EXISTS(SELECT 1 FROM tower_scene_style_approval) OR abs(julianday(NEW.approved_at)-julianday('now'))>1.0/1440 OR (SELECT count(*) FROM tower_scenes WHERE id IN('seed-v1-01','seed-v1-02','seed-v1-05') AND state='reviewed')!=3 BEGIN SELECT RAISE(ABORT,'scene_style_approval_invalid'); END;
CREATE TRIGGER tower_scene_style_no_update BEFORE UPDATE ON tower_scene_style_approval BEGIN SELECT RAISE(ABORT,'scene_style_approval_immutable'); END;
CREATE TRIGGER tower_scene_style_no_delete BEFORE DELETE ON tower_scene_style_approval BEGIN SELECT RAISE(ABORT,'scene_style_approval_permanent'); END;
CREATE TRIGGER tower_scene_style_seed_guard BEFORE INSERT ON tower_scenes WHEN NEW.batch_id LIKE 'initial-v1-%' AND NEW.id NOT IN('seed-v1-01','seed-v1-02','seed-v1-05') AND NOT EXISTS(SELECT 1 FROM tower_scene_style_approval WHERE id=1) BEGIN SELECT RAISE(ABORT,'scene_style_approval_required'); END;
CREATE TRIGGER tower_scene_style_publish_guard BEFORE UPDATE OF state ON tower_scenes WHEN NEW.batch_id LIKE 'initial-v1-%' AND NEW.state='published' AND NOT EXISTS(SELECT 1 FROM tower_scene_style_approval WHERE id=1) BEGIN SELECT RAISE(ABORT,'scene_style_approval_required'); END;
